INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast immer an alle Geräte im Netzwerk sendet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur an definierte Gruppen"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Multicast in einem IT-Netzwerk einrichte?', 3, '[{"text": "Gruppenmanagement", "correct": true, "because": "Definiert Empfänger"}, {"text": "Schnellste Installation", "correct": false, "because": "Effizienz zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Multicast in Netzwerken?', 5, '[{"text": "Effiziente Bandbreitennutzung", "correct": true, "because": "Sendet einmal"}, {"text": "Gruppenadressierung", "correct": true, "because": "Zielt auf Empfänger"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast reduziert Netzwerkverkehr. b) Es sendet immer an Einzelgeräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sendet an Gruppen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Multicast in einem Netzwerk einrichte?', 4, '[{"text": "IGMP-Protokoll", "correct": false, "because": "Managed Gruppen"}, {"text": "Router-Konfiguration", "correct": false, "because": "Leitet Multicast"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast nur in WLAN-Netzwerken genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Multicast in einem IT-Netzwerk?', 3, '[{"text": "Bandbreiteneffizienz", "correct": true, "because": "Reduziert Verkehr"}, {"text": "Schnellste Installation", "correct": false, "because": "Effizienz wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle unterstützen Multicast?', 5, '[{"text": "IGMP", "correct": true, "because": "Managed Gruppen"}, {"text": "PIM", "correct": true, "because": "Leitet Multicast"}, {"text": "Büroplanung", "correct": false, "because": "Kein Protokoll"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Multicast sendet an mehrere Empfänger gleichzeitig. b) Es ist immer ineffizient. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizient bei Gruppen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Multicast in einem Netzwerk einzurichten?', 4, '[{"text": "Multicast-Adressen", "correct": false, "because": "Definieren Empfänger"}, {"text": "Router-Unterstützung", "correct": false, "because": "Leitet Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Multicast dasselbe wie Broadcast?', 2, '[{"text": "Nein", "correct": true, "because": "Gruppen vs. alle"}, {"text": "Ja", "correct": false, "because": "Verschiedene Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Multicast in Netzwerken?', 4, '[{"text": "Reduzierter Verkehr", "correct": true, "because": "Effiziente Übertragung"}, {"text": "Skalierbarkeit", "correct": true, "because": "Geeignet für Gruppen"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast nur für Video-Streaming genutzt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Anwendungen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Multicast effektiv einzurichten?', 3, '[{"text": "IGMP-Konfiguration", "correct": true, "because": "Managed Gruppen"}, {"text": "Schnellste Hardware", "correct": false, "because": "Effizienz wichtiger"}, {"text": "Bunte Kabel", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast nutzt spezielle IP-Adressen. b) Es sendet an alle Geräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur an Gruppen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Multicast?', 5, '[{"text": "Netzwerkkonfiguration", "correct": true, "because": "Sichert Funktion"}, {"text": "Gruppenmanagement", "correct": true, "because": "Definiert Empfänger"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Multicast in einem Netzwerk einrichte?', 3, '[{"text": "Multicast-Routing", "correct": false, "because": "Leitet Daten"}, {"text": "IGMP", "correct": false, "because": "Managed Gruppen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Multicast immer schneller als Unicast?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anwendung"}, {"text": "Ja", "correct": false, "because": "Situationsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast nur für große Netzwerke geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Multicast?', 4, '[{"text": "Gruppenadressierung", "correct": true, "because": "Definiert Empfänger"}, {"text": "Schnellste Installation", "correct": false, "because": "Effizienz zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
